function idx = findClusters(qualityList, qualities)
% find idx where qualityList contains at least one of the patterns in
% qualities

% remove leading/trailing spaces
% also check if each entry in qualityList is a string/char, if not, change
% it
for i = 1:numel(qualityList)
    if ~ischar(qualityList{i}) && ~isstring(qualityList{i})
        qualityList{i} = '';
    end
end
qualityList = strtrim(qualityList);

if any(strcmpi(qualities,'all')) || strcmpi(qualities{1},'all')
    idx = find(~ismember(qualityList,'garbage') & ~ismember(qualityList,'gabrga') & ~ismember(qualityList,'noisy') & ~ismember(qualityList,'real?'));
%     idx = 1:numel(qualityList);
    return
end

% handle unlabeled cluster qualities
for i = 1:numel(qualityList)
    if isempty(qualityList{i})
        qualityList(i) = {'nan'};
    end
%     qualityList(i) = lower(qualityList(i));
end

[~,mask] = patternMatchCellArray(qualityList, qualities, 'any');

idx = find(mask);
end % findClustersfunction [obj,cluid] = removeLowFRClusters(obj,cluid,lowFR,prbnum)
% % Remove low-firing rate units, e.g., all those firing less than lowFR
%   spikes per second on average across all trials.
%
%   The fitted observation noise (diagonal element of R) for a
%   low-firing rate unit will be small, so the neural trajectory may
%   show a deflection each time the neuron spikes.

meanFRs = mean(mean(obj.psth{prbnum},3,'omitnan'),'omitnan');
use = meanFRs > lowFR;

% remove low fr clusters
cluid = cluid(use);
obj.psth{prbnum} = obj.psth{prbnum}(:,use,:);
obj.trialdat{prbnum} = obj.trialdat{prbnum}(:,use,:);

end % removeLowFRClustersfunction obj = alignSpikes(obj,params,prbnum)

if strcmp(params.alignEvent,'moveOnset')
    obj.bp.ev.(params.alignEvent) = findMoveOnset(obj);
end

if strcmp(params.alignEvent,'firstLick')
    % get first lick time for left and right licks
    temp = obj.bp.ev.lickL;
    idx = ~cellfun('isempty',temp);
    outL = zeros(size(temp));
    outL(idx) = cellfun(@(v)v(1),temp(idx));
    temp = obj.bp.ev.lickR;
    idx = ~cellfun('isempty',temp);
    outR = zeros(size(temp));
    outR(idx) = cellfun(@(v)v(1),temp(idx));
    firstLick = zeros(size(temp));
    % firstLick = min(outL,outR), except when outL||outR == 0
    outL(outL==0) = nan;
    outR(outR==0) = nan;
    firstLick = nanmin(outL,outR);
    firstLick(isnan(firstLick)) = 0;
    obj.bp.ev.(params.alignEvent) = firstLick;
end
if strcmp(params.alignEvent,'lastLick')
    % get last lick time for left and right licks
    temp = obj.bp.ev.lickL;
    idx = ~cellfun('isempty',temp);
    outL = zeros(size(temp));
    outL(idx) = cellfun(@(v)v(end),temp(idx));
    temp = obj.bp.ev.lickR;
    idx = ~cellfun('isempty',temp);
    outR = zeros(size(temp));
    outR(idx) = cellfun(@(v)v(end),temp(idx));
    lastLick = zeros(size(temp));
    % lastLick = max(outL,outR), except when outL||outR == 0
    outL(outL==0) = nan;
    outR(outR==0) = nan;
    lastLick = nanmax(outL,outR);
    lastLick(isnan(lastLick)) = 0;
    obj.bp.ev.(params.alignEvent) = lastLick;
end

if strcmp(params.alignEvent,'jawOnset')
    % half rise time to first peak of jaw onset after go cue
    view = 1; % side cam
    [~,jawMask] = patternMatchCellArray(obj.traj{view}(1).featNames,{'jaw'},'all');
    feat = find(jawMask); % jaw

    % filter params
    opts.f_cut = 60; % cutoff freq for butter filt
    opts.f_n   = 2;  % filter order

    % peak finding params
    opts.minpkdist = 0.06; % number of ms around peaks to reject peaks
    opts.minpkprom = 10;   % a threshold for the peak size
    obj.bp.ev.(params.alignEvent) = alignJawOnset(view,feat,obj,opts);
end

% align spikes to params.alignEvent
for clu = 1:numel(obj.clu{prbnum})
    event = obj.bp.ev.(params.alignEvent)(obj.clu{prbnum}(clu).trial);

    obj.clu{prbnum}(clu).trialtm_aligned = obj.clu{prbnum}(clu).trialtm - event;
end

end % alignSpikes
function obj = getSeq(obj,params,prbnum,varargin)

if isfield(obj,'psth')
    obj = rmfield(obj,{'psth','trialdat'});
end

if nargin > 3
    doPSTH = varargin{1};
else
    doPSTH = true;
end

edges = params.tmin:params.dt:params.tmax;
obj.time = edges + params.dt/2;
obj.time = obj.time(1:end-1);

spkedges = params.tmin:0.001:params.tmax;

% get psths by condition
obj.psth{prbnum} = zeros(numel(obj.time),numel(params.cluid{prbnum}),numel(params.condition));
if doPSTH
    for i = 1:numel(params.cluid{prbnum})
        curClu = params.cluid{prbnum}(i);
        for j = 1:numel(params.condition)

            trix = params.trialid{j};

            spkix = ismember(obj.clu{prbnum}(curClu).trial, trix);


            % if no spikes found for current set of trials (trix), move on to
            % next set
            if all(~spkix)
                continue
            end


            N = histc(obj.clu{prbnum}(curClu).trialtm_aligned(spkix), edges);
            N = N(1:end-1);

            obj.psth{prbnum}(:,i,j) = mySmooth(N./numel(trix)./params.dt, params.smooth, params.bctype);  % trial-averaged separated by trial type

        end
    end
end


% get single trial data
obj.trialdat{prbnum} = zeros(numel(obj.time),numel(params.cluid{prbnum}),obj.bp.Ntrials);
% obj.trialspikes{prbnum} = zeros(numel(spkedges),numel(params.cluid{prbnum}),obj.bp.Ntrials);
for i = 1:numel(params.cluid{prbnum})
    curClu = params.cluid{prbnum}(i);
    for j = 1:obj.bp.Ntrials

        spkix = ismember(obj.clu{prbnum}(curClu).trial, j);

        % if no spikes found for current trial (j), move on to
        % next trial
        if all(~spkix)
            continue
        end


        N = histc(obj.clu{prbnum}(curClu).trialtm_aligned(spkix), edges);
        N = N(1:end-1);
        if size(N,2) > size(N,1)
            N = N'; % make sure N is a column vector
        end


        obj.trialdat{prbnum}(:,i,j) = mySmooth(N./params.dt,params.smooth, params.bctype);

        %         % raw spikes
        %         spkN = histc(obj.clu{prbnum}(curClu).trialtm_aligned(spkix), spkedges);
        %         if size(spkN,2) > size(spkN,1)
        %             spkN = spkN'; % make sure N is a column vector
        %         end
        %         spkN(spkN > 1) = 1; % binarize (should only have at most 1 spk in 1 ms bin)
        %         obj.trialspikes{prbnum}(:,i,j) = spkN;

    end
end


end % getSeqroot@c4301b417ebd:/app/code/DataLoadingScripts#

