"""Unified loader for the Hasnain/Birnbaum data_structure_*.mat files.
Handles both MATLAB v7 (scipy.io) and v7.3 (HDF5/h5py) files and returns
plain python dicts / numpy arrays with identical layout.
"""
import numpy as np, h5py, scipy.io as sio

def is_v73(fn):
    with open(fn,'rb') as fh: return b'MATLAB 7.3' in fh.read(128)

# ---------------- v7.3 helpers ----------------
def _h5str(f, ds):
    a = np.array(ds).ravel()
    return ''.join(chr(int(c)) for c in a)

def _load_v73(fn, want_traj=True):
    f = h5py.File(fn,'r')
    o = f['obj']
    out = {}
    bp = o['bp']
    B = {}
    for k in ['Ntrials','L','R','hit','miss','no','early','autowater']:
        if k in bp: B[k]=np.array(bp[k]).ravel()
    B['stim_enable']=np.array(bp['stim']['enable']).ravel() if 'stim' in bp else None
    ev={}
    for k in ['bitStart','sample','delay','goCue','reward']:
        if k in bp['ev']: ev[k]=np.array(bp['ev'][k]).ravel()
    for k in ['lickL','lickR']:
        refs=bp['ev'][k]
        lst=[]
        for i in range(refs.shape[1] if refs.ndim==2 else refs.shape[0]):
            r = refs[0,i] if refs.ndim==2 else refs[i]
            try:
                v=np.array(f[r]).ravel().astype(float)
            except Exception:
                v=np.array([])
            lst.append(v)
        ev[k]=lst
    B['ev']=ev
    out['bp']=B
    # clusters
    clu=[]
    for p in range(o['clu'].shape[0]):
        g=f[o['clu'][p,0]]
        if isinstance(g,h5py.Group) and 'quality' in g:
            n=g['quality'].shape[0]
            qual=[_h5str(f,f[g['quality'][i,0]]).strip() for i in range(n)]
            trialtm=[np.array(f[g['trialtm'][i,0]]).ravel().astype(np.float64) for i in range(n)]
            trial=[np.array(f[g['trial'][i,0]]).ravel().astype(np.int32) for i in range(n)]
            clu.append(dict(quality=qual, trialtm=trialtm, trial=trial))
        else:
            clu.append(None)
    out['clu']=clu
    # trajectories
    if want_traj:
        traj=[]
        for v in range(o['traj'].shape[0]):
            g=f[o['traj'][v,0]]
            ntr=g['ts'].shape[0]
            featNames=[_h5str(f,f[x]) for x in np.array(f[g['featNames'][0,0]]).ravel()]
            ts=[]; ft=[]; nd=[]
            for i in range(ntr):
                a=np.array(f[g['ts'][i,0]])  # (nfeat,3,nframes)
                ts.append(np.transpose(a,(2,1,0)))  # -> (nframes,3,nfeat) matches MATLAB
                ft.append(np.array(f[g['frameTimes'][i,0]]).ravel().astype(np.float64))
                try:
                    nd.append(float(np.array(f[g['NdroppedFrames'][i,0]]).ravel()[0]))
                except Exception:
                    nd.append(np.nan)
            traj.append(dict(featNames=featNames, ts=ts, frameTimes=ft, NdroppedFrames=np.array(nd)))
        out['traj']=traj
    # sglx
    out['sglx']=dict(fs=float(np.array(o['sglx']['fs']).ravel()[0]),
                     bitstart=np.array(o['sglx']['bitcode']['bitstart']).ravel())
    # probe loc
    locs=[]
    try:
        pr=o['ex']['probe']['loc']
        for i in range(pr.shape[0]):
            locs.append(_h5str(f,f[pr[i,0]]).strip('\x00').strip())
    except Exception:
        locs=[]
    out['probe_loc']=locs
    out['_f']=f
    return out

# ---------------- v7 helpers ----------------
def _v7str(x):
    if isinstance(x,str): return x
    a=np.array(x).ravel()
    if a.size==0: return ''
    if a.dtype.kind in 'US': return str(a[0])
    return ''.join(chr(int(c)) for c in a)

def _load_v7(fn, want_traj=True):
    m=sio.loadmat(fn, struct_as_record=False, squeeze_me=True)
    o=m['obj']
    out={}
    bp=o.bp
    B={}
    for k in ['Ntrials','L','R','hit','miss','no','early','autowater']:
        if hasattr(bp,k): B[k]=np.atleast_1d(np.array(getattr(bp,k)).ravel()).astype(float)
    B['stim_enable']=np.array(bp.stim.enable).ravel().astype(float) if hasattr(bp,'stim') else None
    ev={}
    for k in ['bitStart','sample','delay','goCue','reward']:
        if hasattr(bp.ev,k): ev[k]=np.array(getattr(bp.ev,k)).ravel().astype(float)
    for k in ['lickL','lickR']:
        raw=getattr(bp.ev,k)
        lst=[]
        for i in range(len(raw)):
            v=np.atleast_1d(np.array(raw[i]).ravel()).astype(float)
            lst.append(v)
        ev[k]=lst
    B['ev']=ev
    out['bp']=B
    cluarr=o.clu
    if not isinstance(cluarr,np.ndarray): cluarr=np.array([cluarr],dtype=object)
    clu=[]
    for p in range(cluarr.size):
        c=cluarr[p] if cluarr.dtype==object else cluarr
        try:
            n=np.size(c)
            if n==0 or not hasattr(np.atleast_1d(c)[0],'quality'):
                clu.append(None); continue
            cc=np.atleast_1d(c)
            qual=[_v7str(cc[i].quality).strip() for i in range(n)]
            trialtm=[np.atleast_1d(np.array(cc[i].trialtm).ravel()).astype(np.float64) for i in range(n)]
            trial=[np.atleast_1d(np.array(cc[i].trial).ravel()).astype(np.int32) for i in range(n)]
            clu.append(dict(quality=qual,trialtm=trialtm,trial=trial))
        except Exception:
            clu.append(None)
    out['clu']=clu
    if want_traj:
        traj=[]
        trajarr=o.traj
        for v in range(len(trajarr)):
            tv=trajarr[v]
            ntr=np.size(tv)
            tv=np.atleast_1d(tv)
            featNames=[_v7str(x) for x in np.atleast_1d(tv[0].featNames)]
            ts=[];ft=[];nd=[]
            for i in range(ntr):
                a=np.array(tv[i].ts,dtype=float)  # (nframes,3,nfeat)
                ts.append(a)
                ft.append(np.atleast_1d(np.array(tv[i].frameTimes).ravel()).astype(float))
                try: nd.append(float(np.array(tv[i].NdroppedFrames).ravel()[0]))
                except Exception: nd.append(np.nan)
            traj.append(dict(featNames=featNames,ts=ts,frameTimes=ft,NdroppedFrames=np.array(nd)))
        out['traj']=traj
    out['sglx']=dict(fs=float(np.array(o.sglx.fs).ravel()[0]),
                     bitstart=np.array(o.sglx.bitcode.bitstart).ravel().astype(float))
    locs=[]
    try:
        pl=o.ex.probe.loc
        for x in np.atleast_1d(pl): locs.append(_v7str(x).strip())
    except Exception: locs=[]
    out['probe_loc']=locs
    return out

def load_session(fn, want_traj=True):
    return _load_v73(fn,want_traj) if is_v73(fn) else _load_v7(fn,want_traj)

def load_me(fn):
    m=sio.loadmat(fn, struct_as_record=False, squeeze_me=True)
    me=m['me']
    data=[np.atleast_1d(np.array(d).ravel()).astype(float) for d in me.data]
    thresh=float(np.array(me.moveThresh).ravel()[0])
    return dict(data=data, moveThresh=thresh)
